// ─── Levels ───────────────────────────────────────────────────────────────────

const POINTS_PER_LEVEL = 50;

interface LevelInfo { emoji: string; key: string }
const LEVELS: LevelInfo[] = [
  { emoji: '🌱', key: 'daily.level.recruit'    },
  { emoji: '🧭', key: 'daily.level.explorer'   },
  { emoji: '⚔️', key: 'daily.level.adventurer' },
  { emoji: '🦸', key: 'daily.level.hero'       },
  { emoji: '🏆', key: 'daily.level.champion'   },
  { emoji: '🌟', key: 'daily.level.legend'     },
];

function getLevelIndex(pts: number): number {
  return Math.min(Math.floor(pts / POINTS_PER_LEVEL), LEVELS.length - 1);
}
function getLevelNumber(pts: number): number {
  return Math.floor(pts / POINTS_PER_LEVEL) + 1;
}
function getXpProgress(pts: number): number {
  return ((pts % POINTS_PER_LEVEL) / POINTS_PER_LEVEL) * 100;
}

