// ─── Component ────────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [locale] = useLocale();
  const t = useMemo(() => createT(locale, APP_KEYS), [locale]);
  const pt = locale === 'pt';

  const [loaded, setLoaded] = useState(false);
  const [progress, setProgress] = useState<DailyProgress>(freshProgress);
  const [editMode, setEditMode] = useState(false);
  const [showAddForm, setShowAddForm] = useState(false);
  const [flashingIds, setFlashingIds] = useState<Set<string>>(new Set());
  const [floatingPoints, setFloatingPoints] = useState<FloatingPoint[]>([]);
  const [levelUpInfo, setLevelUpInfo] = useState<LevelInfo | null>(null);
  const [levelUpExiting, setLevelUpExiting] = useState(false);
  const [xpShimmer, setXpShimmer] = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);
  const [dragId, setDragId] = useState<string | null>(null);
  const [overId, setOverId] = useState<string | null>(null);
  const floatingIdRef = useRef(0);

  // Load persisted state on mount
  useEffect(() => {
    let cancelled = false;
    loadDailyProgress().then((existing) => {
      if (cancelled) return;
      const today = todayISO();
      if (!existing) {
        setProgress(freshProgress());
      } else {
        const missions = existing.missions && existing.missions.length > 0 ? existing.missions : DEFAULT_MISSIONS;
        // Migrate pre-history state: seed history with what we know (lastResetDate → completedToday)
        const history: Record<string, string[]> = { ...(existing.history ?? {}) };
        if (!existing.history && existing.completedToday.length > 0) {
          history[existing.lastResetDate] = [...existing.completedToday];
        }
        if (existing.lastResetDate !== today) {
          // Commit yesterday's completions into history before resetting the current day
          if (existing.completedToday.length > 0) {
            history[existing.lastResetDate] = [...existing.completedToday];
          }
          setProgress({
            ...existing,
            completedToday: history[today] ?? [],
            lastResetDate: today,
            missions,
            history,
          });
        } else {
          setProgress({
            ...existing,
            missions,
            history,
            completedToday: history[today] ?? existing.completedToday,
          });
        }
      }
      setLoaded(true);
    });
    return () => { cancelled = true; };
  }, []);

  // Persist on every change (after initial load)
  useEffect(() => {
    if (!loaded) return;
    saveDailyProgress(progress);
  }, [progress, loaded]);

  const toggleMission = useCallback((mission: DailyMission, cardEl: HTMLElement | null) => {
    setProgress((prev) => {
      const alreadyDone = prev.completedToday.includes(mission.id);
      const today = todayISO();

      if (alreadyDone) {
        const newPoints = Math.max(0, prev.totalPoints - mission.points);
        const newCompleted = prev.completedToday.filter((id) => id !== mission.id);
        const newStreakDays = newCompleted.length < 3
          ? prev.streakDays.filter((d) => d !== today)
          : prev.streakDays;
        const newHistory = { ...prev.history, [today]: newCompleted };
        return {
          ...prev,
          totalPoints: newPoints,
          totalMissionsCompleted: Math.max(0, prev.totalMissionsCompleted - 1),
          completedToday: newCompleted,
          streakDays: newStreakDays,
          history: newHistory,
        };
      }

      const newPoints = prev.totalPoints + mission.points;
      const newCompleted = [...prev.completedToday, mission.id];
      const newStreakDays = newCompleted.length >= 3 && !prev.streakDays.includes(today)
        ? [...prev.streakDays, today]
        : prev.streakDays;
      const newHistory = { ...prev.history, [today]: newCompleted };

      // Flash animation
      setFlashingIds((fids) => new Set(fids).add(mission.id));
      setTimeout(() => {
        setFlashingIds((fids) => {
          const next = new Set(fids);
          next.delete(mission.id);
          return next;
        });
      }, 600);

      setXpShimmer(true);
      setTimeout(() => setXpShimmer(false), 750);
      navigator.vibrate?.(50);

      if (cardEl) {
        const rect = cardEl.getBoundingClientRect();
        const fpId = ++floatingIdRef.current;
        setFloatingPoints((fps) => [...fps, {
          id: fpId,
          value: mission.points,
          x: rect.right - 60,
          y: rect.top + rect.height / 2,
        }]);
        setTimeout(() => {
          setFloatingPoints((fps) => fps.filter((f) => f.id !== fpId));
        }, 1200);
      }

      const prevLevel = getLevelIndex(prev.totalPoints);
      const newLevel = getLevelIndex(newPoints);
      if (newLevel > prevLevel) {
        setLevelUpInfo(LEVELS[newLevel]);
        setLevelUpExiting(false);
        setTimeout(() => {
          setLevelUpExiting(true);
          setTimeout(() => setLevelUpInfo(null), 450);
        }, 2000);
      }

      return {
        ...prev,
        totalPoints: newPoints,
        totalMissionsCompleted: prev.totalMissionsCompleted + 1,
        completedToday: newCompleted,
        streakDays: newStreakDays,
        history: newHistory,
      };
    });
  }, []);

  const resetDay = useCallback(() => {
    setProgress((prev) => {
      const today = todayISO();
      const newHistory = { ...prev.history };
      delete newHistory[today];
      return {
        ...prev,
        completedToday: [],
        lastResetDate: today,
        history: newHistory,
      };
    });
    setConfirmReset(false);
  }, []);

  const deleteMission = useCallback((id: string) => {
    setProgress((prev) => ({
      ...prev,
      missions: prev.missions.filter((m) => m.id !== id),
      completedToday: prev.completedToday.filter((cid) => cid !== id),
    }));
  }, []);

  const addMission = useCallback((mission: DailyMission) => {
    setProgress((prev) => ({
      ...prev,
      missions: [...prev.missions, mission],
    }));
  }, []);

  const reorderMissions = useCallback((fromId: string, toId: string) => {
    if (fromId === toId) return;
    setProgress((prev) => {
      const arr = prev.missions;
      const fromIdx = arr.findIndex((m) => m.id === fromId);
      const toIdx = arr.findIndex((m) => m.id === toId);
      if (fromIdx < 0 || toIdx < 0) return prev;
      const next = [...arr];
      const [moved] = next.splice(fromIdx, 1);
      next.splice(toIdx, 0, moved);
      return { ...prev, missions: next };
    });
  }, []);

  const levelIdx = getLevelIndex(progress.totalPoints);
  const levelNum = getLevelNumber(progress.totalPoints);
  const levelInfo = LEVELS[levelIdx];
  const xpPct = getXpProgress(progress.totalPoints);
  const pointsIntoLevel = progress.totalPoints % POINTS_PER_LEVEL;
  const streak = computeDailyStreak(progress.streakDays);

  const sorted = editMode
    ? progress.missions
    : [...progress.missions].sort((a, b) => {
        const aDone = progress.completedToday.includes(a.id) ? 1 : 0;
        const bDone = progress.completedToday.includes(b.id) ? 1 : 0;
        return aDone - bDone;
      });

  const isFirstRun = progress.totalPoints === 0 && progress.completedToday.length === 0 && !editMode;

  return (
    <Layout title={t('daily.title')} sidebar={null} topBarRight={topBarRight}>
      <Wrapper>
        <HeroCard>
          <LevelBadge>{levelInfo.emoji}</LevelBadge>
          <LevelKicker>{t('daily.level', { n: levelNum })}</LevelKicker>
          <LevelName>{t(levelInfo.key)}</LevelName>
          <TotalPoints>
            <span>{progress.totalPoints}</span>
            {t('daily.points')}
          </TotalPoints>
          <XpBarWrapper>
            <XpBarLabel>
              <span>{t('daily.xp')}</span>
              <span>{pointsIntoLevel} / {POINTS_PER_LEVEL}</span>
            </XpBarLabel>
            <XpBarTrack>
              <XpBarFill pct={xpPct} shimmer={xpShimmer} />
            </XpBarTrack>
          </XpBarWrapper>
        </HeroCard>

        {isFirstRun && (
          <WelcomeHero>
            <WelcomeRocket>🚀</WelcomeRocket>
            <WelcomeTitle>{t('daily.welcomeTitle')}</WelcomeTitle>
            <WelcomeBody>{t('daily.welcomeBody')}</WelcomeBody>
          </WelcomeHero>
        )}

        <div>
          <SectionRow>
            <SectionTitle>{t('daily.sectionMissions')}</SectionTitle>
            <Button
              variant={editMode ? 'accent' : 'ghost'}
              size="sm"
              icon={editMode ? <Check size={13} /> : <Pencil size={13} />}
              onClick={() => {
                setEditMode((v) => !v);
                setShowAddForm(false);
              }}
            >
              {editMode ? t('daily.done') : t('daily.edit')}
            </Button>
          </SectionRow>

          <MissionList>
            {sorted.map((mission) => {
              const completed = progress.completedToday.includes(mission.id);
              const flashing = flashingIds.has(mission.id);
              const name = pt ? mission.namePt : mission.nameEn;

              if (editMode) {
                const isDragging = dragId === mission.id;
                const isOver = overId === mission.id && dragId !== mission.id;
                return (
                  <MissionCard
                    key={mission.id}
                    completed={false}
                    flashing={false}
                    draggable
                    style={{
                      opacity: isDragging ? 0.3 : 1,
                      cursor: 'default',
                      boxShadow: isOver ? `0 -2px 0 0 ${theme.colors.accent}` : undefined,
                    }}
                    onDragStart={(e) => {
                      setDragId(mission.id);
                      e.dataTransfer.effectAllowed = 'move';
                      e.dataTransfer.setData('text/plain', mission.id);
                    }}
                    onDragOver={(e) => {
                      e.preventDefault();
                      e.dataTransfer.dropEffect = 'move';
                      if (dragId && dragId !== mission.id) setOverId(mission.id);
                    }}
                    onDragLeave={(e) => {
                      if (e.currentTarget === e.target) setOverId(null);
                    }}
                    onDrop={(e) => {
                      e.preventDefault();
                      if (dragId) reorderMissions(dragId, mission.id);
                      setDragId(null);
                      setOverId(null);
                    }}
                    onDragEnd={() => {
                      setDragId(null);
                      setOverId(null);
                    }}
                  >
                    <DragHandle aria-hidden>
                      <GripVertical size={16} />
                    </DragHandle>
                    <MissionInfo>
                      <MissionEmoji>{mission.emoji}</MissionEmoji>
                      <MissionName completed={false}>{name}</MissionName>
                    </MissionInfo>
                    <PointsBadge completed={false}>+{mission.points} pts</PointsBadge>
                    <EditRow>
                      <IconButton
                        tone="danger"
                        onClick={() => deleteMission(mission.id)}
                        title={t('daily.delete')}
                        aria-label={t('daily.delete')}
                      >
                        <Trash2 size={13} />
                      </IconButton>
                    </EditRow>
                  </MissionCard>
                );
              }

              return (
                <MissionCard
                  key={mission.id}
                  completed={completed}
                  flashing={flashing}
                  onClick={(e) => toggleMission(mission, e.currentTarget as HTMLElement)}
                  role="checkbox"
                  aria-checked={completed}
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === ' ' || e.key === 'Enter') {
                      e.preventDefault();
                      toggleMission(mission, e.currentTarget as HTMLElement);
                    }
                  }}
                >
                  <Checkbox checked={completed}>{completed && '✓'}</Checkbox>
                  <MissionInfo>
                    <MissionEmoji>{mission.emoji}</MissionEmoji>
                    <MissionName completed={completed}>{name}</MissionName>
                  </MissionInfo>
                  <PointsBadge completed={completed}>+{mission.points} pts</PointsBadge>
                </MissionCard>
              );
            })}

            {editMode && (
              showAddForm ? (
                <MissionForm
                  t={t}
                  onAdd={(m) => { addMission(m); setShowAddForm(false); }}
                  onCancel={() => setShowAddForm(false)}
                />
              ) : (
                <Button
                  variant="ghost"
                  icon={<Plus size={13} />}
                  onClick={() => setShowAddForm(true)}
                >
                  {t('daily.addMission')}
                </Button>
              )
            )}
          </MissionList>
        </div>

        <div>
          <SectionRow>
            <SectionTitle>{t('daily.sectionStats')}</SectionTitle>
          </SectionRow>
          <StatsGrid>
            <StatCard>
              <StatEmoji>✅</StatEmoji>
              <StatValue>{progress.totalMissionsCompleted}</StatValue>
              <StatLabel>{t('daily.stat.completed')}</StatLabel>
            </StatCard>
            <StatCard>
              <StatEmoji>⭐</StatEmoji>
              <StatValue>{progress.totalPoints}</StatValue>
              <StatLabel>{t('daily.stat.points')}</StatLabel>
            </StatCard>
            <StreakCard>
              <StreakEmoji>🔥</StreakEmoji>
              <StreakValue>{streak}</StreakValue>
              <StreakLabel>{t('daily.stat.streak')}</StreakLabel>
            </StreakCard>
          </StatsGrid>
        </div>

        <div>
          <SectionRow>
            <SectionTitle>{t('daily.sectionWeek')}</SectionTitle>
          </SectionRow>
          <WeekStrip progress={progress} total={progress.missions.length} locale={locale} />
        </div>

        <ActionsRow>
          {confirmReset ? (
            <ConfirmRow>
              <ConfirmText>{t('daily.resetConfirm')}</ConfirmText>
              <ConfirmButtons>
                <Button variant="danger" onClick={resetDay} style={{ flex: 1 }}>
                  {t('daily.confirm')}
                </Button>
                <Button variant="ghost" onClick={() => setConfirmReset(false)} style={{ flex: 1 }}>
                  {t('daily.cancel')}
                </Button>
              </ConfirmButtons>
            </ConfirmRow>
          ) : (
            <Button variant="ghost" onClick={() => setConfirmReset(true)}>
              {t('daily.resetDay')}
            </Button>
          )}
        </ActionsRow>

        {floatingPoints.map((fp) => (
          <FloatingPointEl key={fp.id} style={{ left: fp.x, top: fp.y }}>
            +{fp.value}
          </FloatingPointEl>
        ))}

        {levelUpInfo && (
          <LevelUpOverlay exiting={levelUpExiting}>
            <LevelUpCard>
              <LevelUpEmoji>{levelUpInfo.emoji}</LevelUpEmoji>
              <LevelUpTitle>{t('daily.levelUp')}</LevelUpTitle>
              <LevelUpName>{t(levelUpInfo.key)}</LevelUpName>
            </LevelUpCard>
          </LevelUpOverlay>
        )}
      </Wrapper>
    </Layout>
  );
}

// ─── Week strip ───────────────────────────────────────────────────────────────

interface WeekStripProps {
  progress: DailyProgress;
  total: number;
  locale: string;
}

function WeekStrip({ progress, total, locale }: WeekStripProps) {
  const tLocal = useMemo(() => createT(locale === 'pt' ? 'pt' : 'en', APP_KEYS), [locale]);
  const history: DayStat[] = useMemo(() => getDailyHistory(progress, 7), [progress]);
  const today = todayISO();
  const dayFmt = new Intl.DateTimeFormat(locale === 'pt' ? 'pt-PT' : 'en-US', { weekday: 'short' });

  const level = (count: number): 0 | 1 | 2 | 3 => {
    if (count === 0) return 0;
    if (total === 0) return 1;
    const ratio = count / total;
    if (ratio >= 0.66) return 3;
    if (ratio >= 0.33) return 2;
    return 1;
  };

  return (
    <WeekStripWrapper>
      <WeekRow>
        {history.map((d) => {
          const name = dayFmt.format(new Date(d.date + 'T00:00:00'));
          const ratio = total > 0 ? d.count / total : 0;
          return (
            <DayCell key={d.date} ratio={ratio} isToday={d.date === today}>
              <DayName>{name}</DayName>
              <DayDot level={level(d.count)} />
              <DayCount>{d.count}{total ? `/${total}` : ''}</DayCount>
            </DayCell>
          );
        })}
      </WeekRow>
      <WeekHint>{tLocal('daily.weekHint')}</WeekHint>
    </WeekStripWrapper>
  );
}

// ─── Add-mission form ─────────────────────────────────────────────────────────

interface MissionFormProps {
  t: TFunction;
  onAdd: (mission: DailyMission) => void;
  onCancel: () => void;
}

function MissionForm({ t, onAdd, onCancel }: MissionFormProps) {
  const [emoji, setEmoji] = useState('✨');
  const [name, setName] = useState('');
  const [points, setPoints] = useState(10);

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) return;
    onAdd({
      id: `custom-${Date.now().toString(36)}`,
      emoji: emoji || '✨',
      nameEn: trimmed,
      namePt: trimmed,
      points: Math.max(1, Math.min(100, Math.round(points))),
    });
    setName('');
    setPoints(10);
    setEmoji('✨');
  };

  return (
    <AddForm onSubmit={submit}>
      <EmojiInput
        value={emoji}
        onChange={(e) => setEmoji(e.target.value)}
        maxLength={4}
        aria-label={t('daily.placeholderEmoji')}
      />
      <NameInput
        placeholder={t('daily.placeholderName')}
        value={name}
        onChange={(e) => setName(e.target.value)}
        autoFocus
      />
      <PointsInput
        type="number"
        min={1}
        max={100}
        value={points}
        onChange={(e) => setPoints(Number(e.target.value))}
        aria-label={t('daily.placeholderPoints')}
      />
      <Button variant="primary" size="sm" type="submit">
        {t('daily.add')}
      </Button>
      <Button variant="ghost" size="sm" type="button" onClick={onCancel}>
        {t('daily.cancel')}
      </Button>
    </AddForm>
  );
}
